-- Translators: Claude (AI-assisted, not yet reviewed by a native speaker), Codex (AI-assisted, not yet reviewed by a native speaker)
local addon_name, addon = ...

local L = LibStub("AceLocale-3.0"):NewLocale(addon_name, "deDE", false, true)
if not L then return end

-- Human translators the About page credits (display names only; the AI is named in the header above).
L[0] = {}

addon.translation = {
-- 01059048 English: Retribution (Wowhead & simulator)
[1] = "Vergeltung (Wowhead & Simulation)",
-- 6fc82107 English: Melee Retribution from level 1 to 70, and the default for any Paladin no other
--     premade fits. Opens each target with Judgement of Wisdom (low mana) or the Crusader, keeps
--     your best seal up (Blood or Martyr, Command, then Righteousness), Crusader Strike, judges
--     only Righteousness, Blood or Martyr (or Command on a stunned target), Exorcism on Undead and
--     Demons, Consecration for three or more enemies with mana to spare. Hammer of Wrath is left to
--     you (Wowhead uses it only on fleeing targets). Reminders: Sanctity, Retribution or Devotion
--     Aura, a Blessing on yourself, a heal after the fight, Avenging Wrath. Seal twisting is a
--     separate premade.
[2] = "Vergeltung im Nahkampf von Stufe 1 bis 70 und der Standard für jeden Paladin, zu dem keine andere integrierte Rotation passt. Eröffnet jedes Ziel mit Richturteil der Weisheit (wenig Mana) oder des Kreuzfahrers, hält Ihr bestes Siegel aufrecht (Blut oder Märtyrer, Befehl, dann Rechtschaffenheit), Kreuzfahrerstoß, richtet nur Rechtschaffenheit, Blut oder Märtyrer (oder Befehl auf ein betäubtes Ziel), Exorzismus gegen Untote und Dämonen, Weihe für drei oder mehr Gegner bei überschüssigem Mana. Hammer des Zorns bleibt Ihnen überlassen (Wowhead nutzt ihn nur gegen fliehende Ziele). Erinnerungen: Aura der Heiligkeit, der Vergeltung oder der Hingabe, ein Segen auf Sie selbst, eine Heilung nach dem Kampf, Zornige Vergeltung. Siegel-Twisting ist eine eigene integrierte Rotation.",
-- 89f00a09 English: Retribution (Icy Veins)
-- Context: Name of a Built In (premade) rotation, shown in the rotation list and picker: Paladin,
--     The Burning Crusade Classic (variant key: Retribution / IcyVeins). Names in parentheses
--     (guide or tool such as Icy Veins, Wowhead, SimulationCraft, simulator, Hekili, Mobalytics,
--     Warcraft Tavern) are proper names and stay unchanged.
[3] = "Vergeltung (Icy Veins)",
-- c68e9ea0 English: Icy Veins' Retribution, an alternative to the recommended Wowhead Retribution
--     premade, off by default: enable it and disable that one, or raise its priority. Judgement of
--     the Crusader once per target, Seal of Righteousness (Command only with a slow weapon, Blood
--     or Martyr once learned), Crusader Strike, Hammer of Wrath and Judgement on cooldown,
--     Consecration on two or more enemies, Exorcism on Undead and Demons, and Holy Shock for Holy
--     levelers. Same reminders as the Wowhead variant.
[4] = "Vergeltung nach Icy Veins, eine Alternative zur empfohlenen integrierten Vergeltungsrotation nach Wowhead, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Richturteil des Kreuzfahrers einmal pro Ziel, Siegel der Rechtschaffenheit (Befehl nur mit einer langsamen Waffe, Blut oder Märtyrer, sobald erlernt), Kreuzfahrerstoß, Hammer des Zorns und Richturteil bei Abklingzeit-Ende, Weihe gegen zwei oder mehr Gegner, Exorzismus gegen Untote und Dämonen und Heiliger Schock für Heilig-Leveler. Dieselben Erinnerungen wie die Wowhead-Variante.",
-- 85d846bd English: Retribution seal twisting
-- Context: Name of a Built In (premade) rotation, shown in the rotation list and picker: Paladin,
--     The Burning Crusade Classic (variant key: Retribution / Twist).
[5] = "Vergeltung mit Siegel-Twisting",
-- 34a6a34f English: Off by default; enable it if you twist seals (level 64+, Seal of Command and
--     Blood or Martyr). Opens with Judgement of the Crusader, then each swing puts up Seal of
--     Command (rank 1) early and switches to Blood or Martyr in the last 0.4 seconds, Crusader
--     Strike between twists, judges only Blood or Martyr, Exorcism and Consecration only as
--     fillers, and rolls Blood without twisting below 12% mana. Needs a reliable swing timer;
--     latency is not accounted for.
[6] = "Standardmäßig deaktiviert; aktivieren Sie sie, wenn Sie Siegel twisten (ab Stufe 64, Siegel des Befehls und Blut oder Märtyrer). Eröffnet mit Richturteil des Kreuzfahrers, dann setzt jeder Schlag früh Siegel des Befehls (Rang 1) und wechselt in den letzten 0,4 Sekunden zu Blut oder Märtyrer, Kreuzfahrerstoß zwischen den Wechseln, richtet nur Blut oder Märtyrer, Exorzismus und Weihe nur als Füller und hält unter 12 % Mana Blut ohne Twisting aufrecht. Benötigt einen zuverlässigen Schlagtimer; die Latenz wird nicht berücksichtigt.",
-- b9e3d93c English: Protection (Wowhead & simulator)
[7] = "Schutz (Wowhead & Simulation)",
-- c9c2efbf English: Tanking for the Protection tree or any Paladin with Righteous Fury on. Pulls
--     with Holy Shield, Avenger's Shield and Judgement; against a crushing target (world boss or
--     three or more levels above you) Holy Shield comes first; then Consecration, Exorcism on
--     Undead and Demons, Judgement, Holy Shield, Holy Wrath on undead packs, Avenger's Shield
--     except on crushing targets. Seal of Wisdom on packs when mana is short, Righteousness
--     otherwise. Reminders: Righteous Fury, Devotion Aura, Sanctuary (or Kings, or Wisdom),
--     Avenging Wrath, Lay on Hands. Taunts and target swaps stay with you.
[8] = "Tanken für den Schutzbaum oder jeden Paladin mit aktivem Zorn der Gerechtigkeit. Zieht mit Heiligem Schild, Schild des Rächers und Richturteil; gegen ein Ziel mit zerschmetternden Schlägen (Weltboss oder drei oder mehr Stufen über Ihnen) kommt Heiliger Schild zuerst; dann Weihe, Exorzismus gegen Untote und Dämonen, Richturteil, Heiliger Schild, Heiliger Zorn gegen Gruppen von Untoten, Schild des Rächers außer gegen Ziele mit zerschmetternden Schlägen. Siegel der Weisheit gegen Gruppen bei knappem Mana, sonst Rechtschaffenheit. Erinnerungen: Zorn der Gerechtigkeit, Aura der Hingabe, Refugium (oder Könige oder Weisheit), Zornige Vergeltung, Handauflegung. Spotten und Zielwechsel bleiben Ihnen überlassen.",
-- 3ae9045e English: Icy Veins' tanking, an alternative to the recommended Wowhead Protection
--     premade, off by default: enable it and disable that one, or raise its priority. Judgement of
--     the Crusader when nobody keeps it up, Righteousness (Wisdom on packs), Consecration as the
--     main threat, Judgement, Holy Shield, then Avenger's Shield and Hammer of Wrath on cooldown.
--     Same reminders as the Wowhead variant without Avenging Wrath.
[9] = "Tanken nach Icy Veins, eine Alternative zur empfohlenen integrierten Schutzrotation nach Wowhead, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Richturteil des Kreuzfahrers, wenn niemand es aufrechterhält, Rechtschaffenheit (Weisheit gegen Gruppen), Weihe als Hauptquelle der Bedrohung, Richturteil, Heiliger Schild, dann Schild des Rächers und Hammer des Zorns bei Abklingzeit-Ende. Dieselben Erinnerungen wie die Wowhead-Variante, ohne Zornige Vergeltung.",
-- 9d88b75a English: Holy (Icy Veins & Wowhead)
[10] = "Heilig (Icy Veins & Wowhead)",
-- 879586c5 English: Healing for a Holy Paladin in a group, on your friendly target: Lay on Hands or
--     Holy Shock for a dying target, Cleanse (Purify before 42), Holy Shock while moving, Holy
--     Light for heavy damage, rank-5 Holy Light to keep Light's Grace up, Flash of Light otherwise.
--     With a hostile target it keeps Judgement of Wisdom up. Reminders: Concentration Aura,
--     Blessing of Wisdom, Divine Illumination and Divine Favor. A soloing Holy Paladin gets a
--     Retribution premade instead.
[11] = "Heilung für einen Heilig-Paladin in einer Gruppe, auf Ihr freundliches Ziel: Handauflegung oder Heiliger Schock für ein sterbendes Ziel, Reinigung des Glaubens (Läutern vor Stufe 42), Heiliger Schock in Bewegung, Heiliges Licht bei hohem Schaden, Heiliges Licht Rang 5, um Anmut des Lichts aufrechtzuerhalten, sonst Lichtblitz. Mit einem feindlichen Ziel hält sie Richturteil der Weisheit aufrecht. Erinnerungen: Aura der Konzentration, Segen der Weisheit, Göttliche Eingebung und Göttliche Gunst. Ein Heilig-Paladin im Solospiel erhält stattdessen eine integrierte Vergeltungsrotation.",
-- 2261d994 English: Holy (Wowhead tank healing)
[12] = "Heilig (Wowhead, Tankheilung)",
-- 63b194ff English: Wowhead's raid tank healing, an alternative to the recommended Holy premade,
--     off by default: enable it and disable that one, or raise its priority. Holy Light whenever
--     your target is missing a tenth of their health, Flash of Light only for small deficits, with
--     the same emergencies, cleansing, Judgement and reminders as the blended Holy premade.
[13] = "Schlachtzugs-Tankheilung nach Wowhead, eine Alternative zur empfohlenen integrierten Heilig-Rotation, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Heiliges Licht, sobald Ihrem Ziel ein Zehntel seiner Gesundheit fehlt, Lichtblitz nur bei kleinen Defiziten, mit denselben Notfällen, Reinigungen, Richturteilen und Erinnerungen wie die kombinierte integrierte Heilig-Rotation.",
-- 4d5c0907 English: Retribution and every melee Paladin from level 1 to 60, and the Forever Paladin
--     default. Keeps a damage seal up, refreshed only when it runs low: Seal of the Crusader judged
--     once on an elite target, then Seal of Command with a slow (3.0 s) weapon, else Seal of
--     Righteousness. Then Holy Strike on cooldown, Holy Shock and Light's Vigil for a Shockadin,
--     Exorcism on Undead and Demons, Consecration on three or more enemies, Hammer of Wrath when it
--     can be cast, and melee. Judgement is off the global cooldown, so it is a reminder whenever a
--     seal is up. Other reminders: your aura and Blessing (Retribution Aura and Kings once learned;
--     yours are kept). Optional step, off by default: Hammer of Justice before a Seal of Command
--     Judgement. Mana, health and the swing timer are hidden from addons on Forever, so mana
--     saving, healing yourself, Lay on Hands and Twist of Light seal swapping are your call. Built
--     from level-30 beta guides.
[14] = "Vergeltung und jeder Nahkampf-Paladin von Stufe 1 bis 60 und der Forever-Paladin-Standard. Hält ein Schadenssiegel aufrecht, das nur erneuert wird, wenn es ausläuft: Siegel des Kreuzfahrers einmal gegen ein Elite-Ziel gerichtet, dann Siegel des Befehls mit einer langsamen Waffe (3,0 s), sonst Siegel der Rechtschaffenheit. Dann Heiliger Stoß bei Abklingzeit-Ende, Heiliger Schock und Lichtwacht für einen Shockadin, Exorzismus gegen Untote und Dämonen, Weihe gegen drei oder mehr Gegner, Hammer des Zorns, wenn er gewirkt werden kann, und Nahkampf. Richturteil unterliegt nicht der globalen Abklingzeit, daher ist es eine Erinnerung, wann immer ein Siegel aktiv ist. Weitere Erinnerungen: Ihre Aura und Ihr Segen (Aura der Vergeltung und Könige, sobald erlernt; Ihre eigenen bleiben erhalten). Optionaler, standardmäßig deaktivierter Schritt: Hammer der Gerechtigkeit vor einem Richturteil mit Siegel des Befehls. Mana, Gesundheit und die Schlagzeit sind für Addons unter Forever verborgen, daher entscheiden Sie selbst über Manasparen, Selbstheilung, Handauflegung und den Siegelwechsel mit Wendung des Lichts. Erstellt aus Beta-Leitfäden für Stufe 30.",
-- 2ba64aad English: Protection (Wowhead)
-- Context: Name of a Built In (premade) rotation, shown in the rotation list and picker: Paladin,
--     WoW Forever (variant key: Protection). Names in parentheses (guide or tool such as Icy Veins,
--     Wowhead, SimulationCraft, simulator, Hekili, Mobalytics, Warcraft Tavern) are proper names
--     and stay unchanged.
[15] = "Schutz (Wowhead)",
-- 65aad40e English: Tanking, once Protection is your main talent tree or you turn on Righteous
--     Fury. When the target is fighting someone else: Judgement with Seal of Fury (the taunt),
--     Swift Judgement to reset it. Two or more enemies engaged: Consecration, Exorcism and Holy
--     Wrath on Undead and Demons, Holy Strike. One enemy: Exorcism on Undead and Demons, Holy
--     Strike, Consecration. Reminders: Righteous Fury, Seal of Fury, Judgement on cooldown, Holy
--     Shield while tanking, your aura and Blessing. Health and mana are hidden from addons on
--     Forever, so Templar's Bulwark and Lay on Hands are your call. Pulling, positioning and other
--     taunts stay with you.
[16] = "Tanken, sobald Schutz Ihr Haupttalentbaum ist oder Sie Zorn der Gerechtigkeit aktivieren. Wenn das Ziel gegen jemand anderen kämpft: Richturteil mit Siegel des Furors (der Spott), Schnelles Richturteil, um es zurückzusetzen. Zwei oder mehr Gegner im Kampf: Weihe, Exorzismus und Heiliger Zorn gegen Untote und Dämonen, Heiliger Stoß. Ein Gegner: Exorzismus gegen Untote und Dämonen, Heiliger Stoß, Weihe. Erinnerungen: Zorn der Gerechtigkeit, Siegel des Furors, Richturteil bei Abklingzeit-Ende, Heiliger Schild beim Tanken, Ihre Aura und Ihr Segen. Gesundheit und Mana sind für Addons unter Forever verborgen, daher entscheiden Sie selbst über Bollwerk des Templers und Handauflegung. Pullen, Positionierung und anderes Spotten bleiben Ihnen überlassen.",
-- 6bae5e51 English: Protection, Consecration first (Icy Veins)
[17] = "Schutz, Weihe zuerst (Icy Veins)",
-- 7d470fde English: Icy Veins' tanking style, an alternative to the recommended Wowhead Protection
--     premade, off by default: enable it and disable that one, or raise its priority. Consecration
--     first whenever you can afford it, on one enemy too; Judgement is kept for taunts (no
--     on-cooldown reminder), with Swift Judgement to reset it; then Holy Strike and Exorcism on
--     Undead and Demons. Same tank reminders otherwise.
[18] = "Tankstil nach Icy Veins, eine Alternative zur empfohlenen integrierten Schutzrotation nach Wowhead, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Weihe zuerst, wann immer Sie es sich leisten können, auch gegen einen einzelnen Gegner; Richturteil wird für Spott aufgespart (keine Erinnerung bei Abklingzeit-Ende), mit Schnellem Richturteil zum Zurücksetzen; dann Heiliger Stoß und Exorzismus gegen Untote und Dämonen. Ansonsten dieselben Tank-Erinnerungen.",
-- 23d8ec27 English: Group healing once Holy is your main talent tree with 21 points (Holy Shock's
--     tier), while Righteous Fury is off (a grouped Shockadin lands here too). Heals your current
--     friendly target: Holy Shock on a target with your Light's Vigil, Light's Vigil in combat,
--     Cleanse or Purify, Holy Shock while moving, Holy Light with Infusion of Light, Flash of Light
--     as the main heal. On an enemy: Judgement of Light when Seal of Light is up, Holy Shock,
--     Light's Vigil, Holy Strike, Exorcism. Reminders: Seal of Light when you have no seal, Divine
--     Favor in combat on a friendly target, your aura and Blessing. Health and mana are hidden from
--     addons on Forever, so the target you pick is the only sign of who needs healing; emergency
--     Holy Shocks, big Holy Lights and Lay on Hands are your call.
[19] = "Gruppenheilung, sobald Heilig Ihr Haupttalentbaum mit 21 Punkten ist (die Stufe von Heiliger Schock), solange Zorn der Gerechtigkeit aus ist (ein Shockadin in einer Gruppe landet ebenfalls hier). Heilt Ihr aktuelles freundliches Ziel: Heiliger Schock auf ein Ziel mit Ihrer Lichtwacht, Lichtwacht im Kampf, Reinigung des Glaubens oder Läutern, Heiliger Schock in Bewegung, Heiliges Licht mit Lichtinfusion, Lichtblitz als Hauptheilung. Gegen einen Gegner: Richturteil des Lichts, wenn Siegel des Lichts aktiv ist, Heiliger Schock, Lichtwacht, Heiliger Stoß, Exorzismus. Erinnerungen: Siegel des Lichts, wenn Sie kein Siegel haben, Göttliche Gunst im Kampf auf ein freundliches Ziel, Ihre Aura und Ihr Segen. Gesundheit und Mana sind für Addons unter Forever verborgen, daher ist das Ziel, das Sie wählen, der einzige Hinweis darauf, wer Heilung braucht; Heilige Schocks im Notfall, große Heilige Lichter und Handauflegung bleiben Ihnen überlassen.",
-- b959207f English: Holy, Holy Shock on cooldown (Wowhead)
[20] = "Heilig, Heiliger Schock bei Abklingzeit-Ende (Wowhead)",
-- f6c7691e English: Wowhead's healing style, an alternative to the recommended Holy premade, off by
--     default: enable it and disable that one, or raise its priority. Holy Shock as a routine heal
--     on cooldown, dispels, Flash of Light (health is hidden on Forever, so Holy Light for big
--     deficits is your call). On an enemy it keeps your Judgement of Light up by swapping to Seal
--     of Light, judging and swapping back to Seal of Righteousness, then Holy Strike, Exorcism on
--     Undead and Demons, Holy Shock and Consecration. Same reminders as the Holy premade.
[21] = "Heilstil nach Wowhead, eine Alternative zur empfohlenen integrierten Heilig-Rotation, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Heiliger Schock als Routineheilung bei Abklingzeit-Ende, Bannungen, Lichtblitz (die Gesundheit ist unter Forever verborgen, daher bleibt Heiliges Licht bei großen Defiziten Ihnen überlassen). Gegen einen Gegner hält sie Ihr Richturteil des Lichts aufrecht, indem sie zu Siegel des Lichts wechselt, richtet und zu Siegel der Rechtschaffenheit zurückwechselt, dann Heiliger Stoß, Exorzismus gegen Untote und Dämonen, Heiliger Schock und Weihe. Dieselben Erinnerungen wie die integrierte Heilig-Rotation.",
-- d3e8f0e2 English: Recommended for Retribution in Midnight. In combat the game now hides buffs,
--     debuffs, cooldown times and health from addons, so this shows Blizzard's own Assisted Combat
--     suggestion (the one-button rotation) on your action bars, and stops while you cast or have no
--     enemy targeted. It also reminds you of what that suggestion never covers: an aura between
--     pulls, Rebuke on an interruptible cast, and Divine Protection whenever it is ready in combat.
--     Health is hidden on Retail, so when to use Divine Protection and Lay on Hands is your call.
--     Trinkets and racials stay with you.
[22] = "Empfohlen für Vergeltung in Midnight. Im Kampf verbirgt das Spiel nun Stärkungs- und Schwächungszauber, Abklingzeiten und Gesundheit vor Addons, daher zeigt diese Rotation den eigenen Vorschlag von Blizzards Kampfassistent (die Ein-Tasten-Rotation) auf Ihren Aktionsleisten und pausiert, während Sie wirken oder kein Gegner anvisiert ist. Sie erinnert Sie außerdem an das, was dieser Vorschlag nie abdeckt: eine Aura zwischen den Kämpfen, Zurechtweisung bei einem unterbrechbaren Zauber und Göttlicher Schutz, wann immer er im Kampf bereit ist. Die Gesundheit ist unter Retail verborgen, daher bleibt der Einsatz von Göttlichem Schutz und Handauflegung Ihnen überlassen. Schmuckstücke und Volksfähigkeiten bleiben Ihnen überlassen.",
-- 66c84fb8 English: Reference only, off by default: the Icy Veins and SimulationCraft order reads
--     buffs, charges and enemy counts that Midnight hides in combat, so it cannot run reliably
--     there. Hammer of Light; a free Divine Purpose spender; at 5 Holy Power while Wake of Ashes is
--     cooling, the spender; Wake of Ashes; Divine Toll; Blade of Justice on Art of War; Hammer of
--     Wrath before it caps; at 3 or more Holy Power, Divine Storm on two or more enemies (or with
--     Empyrean Power), else Final Verdict; Hammer of Wrath; Blade of Justice; Judgment; Templar
--     Strike or Crusader Strike. Holy Power stays visible in combat, so its spending points work
--     there. Reminders: Avenging Wrath, Execution Sentence with Wake of Ashes ready, aura, Rebuke,
--     defensives.
[23] = "Nur als Referenz, standardmäßig deaktiviert: die Reihenfolge von Icy Veins und SimulationCraft liest Stärkungszauber, Aufladungen und Gegnerzahlen, die Midnight im Kampf verbirgt, daher kann sie dort nicht zuverlässig laufen. Hammer des Lichts; ein kostenloser Finisher durch Göttliche Bestimmung; bei 5 Heiliger Kraft, während Aschewelle abklingt, der Finisher; Aschewelle; Göttlicher Glockenschlag; Klinge der Gerechtigkeit bei Kunst des Krieges; Hammer des Zorns, bevor seine Aufladungen das Maximum erreichen; ab 3 Heiliger Kraft Göttlicher Sturm gegen zwei oder mehr Gegner (oder mit Himmlischer Macht), sonst Letztes Urteil; Hammer des Zorns; Klinge der Gerechtigkeit; Richturteil; Templerstoß oder Kreuzfahrerstoß. Heilige Kraft bleibt im Kampf sichtbar, daher funktionieren die Schritte, die sie ausgeben, dort. Erinnerungen: Zornige Vergeltung, Todesurteil bei bereiter Aschewelle, Aura, Zurechtweisung, Defensivfähigkeiten.",
-- 3e1487eb English: Recommended for Protection in Midnight. Shows Blizzard's Assisted Combat
--     suggestion, which already includes Shield of the Righteous, Avenging Wrath and Sentinel, and
--     stops while you cast or have no enemy targeted. Reminders for what it leaves out: an aura
--     between pulls, Rebuke on an interruptible cast, and Ardent Defender and Guardian of Ancient
--     Kings whenever they are ready in combat. Health is hidden on Retail, so when to use them, and
--     Lay on Hands, is your call. Taunting and positioning stay with you.
[24] = "Empfohlen für Schutz in Midnight. Zeigt den Vorschlag von Blizzards Kampfassistent, der Schild der Rechtschaffenen, Zornige Vergeltung und Schildwache bereits enthält, und pausiert, während Sie wirken oder kein Gegner anvisiert ist. Erinnerungen an das, was er auslässt: eine Aura zwischen den Kämpfen, Zurechtweisung bei einem unterbrechbaren Zauber sowie Unermüdlicher Verteidiger und Wächter der Uralten Könige, wann immer sie im Kampf bereit sind. Die Gesundheit ist unter Retail verborgen, daher bleibt der Einsatz dieser Fähigkeiten und von Handauflegung Ihnen überlassen. Spotten und Positionierung bleiben Ihnen überlassen.",
-- f169797b English: Reference only, off by default: the Icy Veins and SimulationCraft order needs
--     the Consecration, Vanguard and Shining Light buffs, which Midnight hides in combat.
--     Consecration before the pull; then Divine Toll, Hammer of Light, Consecration when you are
--     not standing in it, Avenger's Shield with Vanguard, Shield of the Righteous at 3 or more Holy
--     Power, Hammer of Wrath, Judgment, Blessed Hammer or Hammer of the Righteous, Avenger's
--     Shield, Word of Glory with Shining Light, Consecration. Reminders: Avenging Wrath or
--     Sentinel, Holy Bulwark, Sacred Weapon outside Avenging Wrath, defensives, aura, Rebuke.
[25] = "Nur als Referenz, standardmäßig deaktiviert: die Reihenfolge von Icy Veins und SimulationCraft braucht die Stärkungszauber Weihe, Vorhut und Strahlendes Licht, die Midnight im Kampf verbirgt. Weihe vor dem Pull; dann Göttlicher Glockenschlag, Hammer des Lichts, Weihe, wenn Sie nicht darin stehen, Schild des Rächers mit Vorhut, Schild der Rechtschaffenen ab 3 Heiliger Kraft, Hammer des Zorns, Richturteil, Gesegneter Hammer oder Hammer der Rechtschaffenen, Schild des Rächers, Wort der Herrlichkeit mit Strahlendem Licht, Weihe. Erinnerungen: Zornige Vergeltung oder Schildwache, Heiliges Bollwerk, Heilige Waffe außerhalb von Zorniger Vergeltung, Defensivfähigkeiten, Aura, Zurechtweisung.",
-- 58e3f59f English: Consecration filler reference (Wowhead)
[26] = "Weihe als Füller, Referenz (Wowhead)",
-- 356b61a8 English: Reference only, off by default: Wowhead's tank order. Judgment on cooldown,
--     Shield of the Righteous, Avenger's Shield, Divine Toll at 0 Holy Power, Blessed Hammer or
--     Hammer of the Righteous, and Consecration only as the filler. Health is hidden on Retail, so
--     Word of Glory below half health is left to you. Same reminders as the Icy Veins reference.
[27] = "Nur als Referenz, standardmäßig deaktiviert: die Tank-Reihenfolge von Wowhead. Richturteil bei Abklingzeit-Ende, Schild der Rechtschaffenen, Schild des Rächers, Göttlicher Glockenschlag bei 0 Heiliger Kraft, Gesegneter Hammer oder Hammer der Rechtschaffenen und Weihe nur als Füller. Die Gesundheit ist unter Retail verborgen, daher bleibt Wort der Herrlichkeit unter halber Gesundheit Ihnen überlassen. Dieselben Erinnerungen wie die Referenz nach Icy Veins.",
-- ce9bbe93 English: Holy in Midnight, for reference: Rotation Master picks a spell, not a target,
--     and the game hides everyone's health in combat, so this keeps your Holy Power and cooldowns
--     turning over on whatever you target and leaves deciding who needs healing to you. Holy Power
--     stays visible in combat, so it is spent at 5 first and at 3 or more after your other heals.
--     On a friendly target: Eternal Flame or Word of Glory at 5 Holy Power, Flash of Light on
--     Infusion of Light, Holy Shock, Eternal Flame or Word of Glory at 3 or more, Holy Light, Flash
--     of Light; Light of Dawn is left to you. On an enemy: Shield of the Righteous at 5 Holy Power,
--     Holy Shock, Shield of the Righteous at 3 or more, Judgment, Crusader Strike, Consecration.
--     Reminders in combat: Divine Toll, Holy Prism, Holy Bulwark or Sacred Weapon, Beacon of Virtue
--     on a friendly target, Divine Protection; an aura between pulls; Rebuke. Lay on Hands is left
--     to you. Avenging Wrath and Aura Mastery are left to you.
[28] = "Heilig in Midnight, als Referenz: Rotation Master wählt einen Zauber, kein Ziel, und das Spiel verbirgt im Kampf die Gesundheit aller, daher hält diese Rotation Ihre Heilige Kraft und Abklingzeiten auf jedem Ziel, das Sie anvisieren, in Gang und überlässt Ihnen die Entscheidung, wer Heilung braucht. Heilige Kraft bleibt im Kampf sichtbar, daher wird sie zuerst bei 5 ausgegeben und ab 3 nach Ihren anderen Heilungen. Bei einem freundlichen Ziel: Ewige Flamme oder Wort der Herrlichkeit bei 5 Heiliger Kraft, Lichtblitz bei Lichtinfusion, Heiliger Schock, Ewige Flamme oder Wort der Herrlichkeit ab 3, Heiliges Licht, Lichtblitz; Licht der Morgendämmerung bleibt Ihnen überlassen. Bei einem Gegner: Schild der Rechtschaffenen bei 5 Heiliger Kraft, Heiliger Schock, Schild der Rechtschaffenen ab 3, Richturteil, Kreuzfahrerstoß, Weihe. Erinnerungen im Kampf: Göttlicher Glockenschlag, Heiliges Prisma, Heiliges Bollwerk oder Heilige Waffe, Leuchtfeuer der Tugend auf einem freundlichen Ziel, Göttlicher Schutz; eine Aura zwischen den Kämpfen; Zurechtweisung. Handauflegung bleibt Ihnen überlassen. Zornige Vergeltung und Aurenmeisterschaft bleiben Ihnen überlassen.",
-- 4c581641 English: Recommended before you choose a specialization (while the game reports the
--     Paladin's initial specialization). Highlights the spell Blizzard's Assisted Combat suggests
--     next, the one rotation advice the game still lets an addon read in Midnight combat; it waits
--     while you cast or channel. Alongside it, the reminders every Paladin premade shares, each
--     once you know its spell. When you choose a specialization at level 10, that specialization's
--     premades take over.
[29] = "Empfohlen, bevor Sie eine Spezialisierung wählen (solange das Spiel die Anfangsspezialisierung des Paladins meldet). Hebt den Zauber hervor, den Blizzards Kampfassistent als Nächstes vorschlägt, den einzigen Rotationshinweis, den das Spiel ein Addon im Kampf in Midnight noch auslesen lässt; sie wartet, während Sie wirken oder kanalisieren. Daneben die Erinnerungen, die jede integrierte Paladin-Rotation teilt, jeweils sobald Sie den Zauber kennen. Wenn Sie auf Stufe 10 eine Spezialisierung wählen, übernehmen die integrierten Rotationen dieser Spezialisierung.",
-- 623b26cb English: Melee Retribution from level 1 to 60, and the default for any Paladin no other
--     premade fits. On elites and long fights outside raids, puts up Seal of the Crusader and
--     judges it once; otherwise keeps a seal up (Command with a weapon of 3.5 seconds or slower,
--     else Righteousness), Exorcism and Holy Wrath on Undead and Demons, Hammer of Wrath, Judgement
--     on cooldown, Consecration while Vengeance is up or on two or more close enemies. Reminders:
--     Sanctity, Retribution or Devotion Aura, Blessing of Wisdom solo or Might in a group, a heal
--     between fights, Divine Shield, Divine Protection or Lay on Hands when you are about to die.
--     Seal twisting is a separate premade; target choice and positioning stay with you.
[30] = "Vergeltung im Nahkampf von Stufe 1 bis 60 und der Standard für jeden Paladin, zu dem keine andere integrierte Rotation passt. Gegen Elitegegner und bei langen Kämpfen außerhalb von Schlachtzügen setzt sie Siegel des Kreuzfahrers und richtet es einmal; sonst hält sie ein Siegel aufrecht (Befehl mit einer Waffe von 3,5 Sekunden oder langsamer, sonst Rechtschaffenheit), Exorzismus und Heiliger Zorn gegen Untote und Dämonen, Hammer des Zorns, Richturteil bei Abklingzeit-Ende, Weihe, solange Rache aktiv ist, oder gegen zwei oder mehr nahe Gegner. Erinnerungen: Aura der Heiligkeit, der Vergeltung oder der Hingabe, Segen der Weisheit solo oder Macht in einer Gruppe, eine Heilung zwischen den Kämpfen, Gottesschild, Göttlicher Schutz oder Handauflegung, wenn Sie kurz vor dem Tod stehen. Siegel-Twisting ist eine eigene integrierte Rotation; Zielwahl und Positionierung bleiben Ihnen überlassen.",
-- a2754c34 English: Retribution, seal twisting
-- Context: Name of a Built In (premade) rotation, shown in the rotation list and picker: Paladin,
--     Classic Era (variant key: Retribution / Twist).
[31] = "Vergeltung, Siegel-Twisting",
-- 34017594 English: Off by default; enable it if you twist seals. For a Retribution Paladin with
--     Seal of Command: keeps Seal of Righteousness up, swaps to rank-1 Seal of Command in the last
--     0.4 seconds before a swing and back again, Judgement whenever it is ready, Exorcism and Holy
--     Wrath on Undead and Demons, Hammer of Wrath, Consecration with Vengeance. Needs a lot of mana
--     and good timing. Same reminders as the Retribution premade.
[32] = "Standardmäßig deaktiviert; aktivieren Sie sie, wenn Sie Siegel twisten. Für einen Vergeltungspaladin mit Siegel des Befehls: hält Siegel der Rechtschaffenheit aufrecht, wechselt in den letzten 0,4 Sekunden vor einem Schlag zu Siegel des Befehls Rang 1 und wieder zurück, Richturteil, sobald es bereit ist, Exorzismus und Heiliger Zorn gegen Untote und Dämonen, Hammer des Zorns, Weihe mit Rache. Benötigt viel Mana und gutes Timing. Dieselben Erinnerungen wie die integrierte Vergeltungsrotation.",
-- 8b566adc English: Tanking from level 1 to 60, chosen by Righteous Fury or the Protection tree.
--     Seal of Righteousness (Seal of Wisdom when mana drops below 40%), Holy Shield and Judgement
--     to pull, Holy Shield kept up, Consecration and Holy Wrath (Undead and Demons) when two or
--     more enemies are on you, otherwise Judgement of the Crusader once, then Judgement and
--     Consecration with mana to spare, Exorcism on Undead and Demons. Reminders: Righteous Fury,
--     Devotion Aura, Sanctuary, Kings or Might, Lay on Hands when nearly dead. Taunting, Blessing
--     of Kings spam and spell ranks stay with you.
[33] = "Tanken von Stufe 1 bis 60, gewählt durch Zorn der Gerechtigkeit oder den Schutzbaum. Siegel der Rechtschaffenheit (Siegel der Weisheit, wenn das Mana unter 40 % fällt), Heiliger Schild und Richturteil zum Ziehen, Heiliger Schild aufrechterhalten, Weihe und Heiliger Zorn (Untote und Dämonen), wenn zwei oder mehr Gegner gegen Sie kämpfen, sonst einmal Richturteil des Kreuzfahrers, dann Richturteil und Weihe bei überschüssigem Mana, Exorzismus gegen Untote und Dämonen. Erinnerungen: Zorn der Gerechtigkeit, Aura der Hingabe, Refugium, Könige oder Macht, Handauflegung kurz vor dem Tod. Spotten, Dauereinsatz von Segen der Könige und Zauberränge bleiben Ihnen überlassen.",
-- f094f171 English: Protection, Seal of Wisdom (Icy Veins)
[34] = "Schutz, Siegel der Weisheit (Icy Veins)",
-- 6af9c398 English: Icy Veins' raid tanking with Wowhead's Wisdom rotation, an alternative to the
--     recommended Protection premade, off by default: enable it and disable that one, or raise its
--     priority. Keeps Seal of Wisdom up and judges it whenever the target lacks Judgement of
--     Wisdom, otherwise judges only to pull; Holy Shield, Consecration every cooldown, Holy Wrath
--     on Undead and Demon packs, Exorcism, and Greater Blessing of Kings as the threat filler in a
--     raid. Same reminders as the recommended premade.
[35] = "Schlachtzugstanken nach Icy Veins mit der Weisheitsrotation von Wowhead, eine Alternative zur empfohlenen integrierten Schutzrotation, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Hält Siegel der Weisheit aufrecht und richtet es, wann immer dem Ziel Richturteil der Weisheit fehlt, sonst richtet sie nur zum Ziehen; Heiliger Schild, Weihe bei jedem Abklingzeit-Ende, Heiliger Zorn gegen Gruppen von Untoten und Dämonen, Exorzismus und Großer Segen der Könige als Bedrohungsfüller im Schlachtzug. Dieselben Erinnerungen wie die empfohlene integrierte Rotation.",
-- 9d4ec18a English: Healing in a group with the Holy tree, from level 10. Acts on your friendly
--     target and picks the heal by missing health: Cleanse or Purify, Holy Shock while you move,
--     maximum-rank Holy Light below 40%, rank-6 Holy Light below 65%, maximum-rank Flash of Light
--     below 85%, rank-4 Flash of Light below 95%. With an enemy in melee range: Seal of Wisdom and,
--     outside raids, Judgement. Reminders: Concentration or Devotion Aura, Blessing of Wisdom,
--     Divine Favor and Lay on Hands for a target that is very low. Choosing whom to heal stays with
--     you; soloing Holy Paladins get the Retribution premade.
[36] = "Heilung in einer Gruppe mit dem Heilig-Baum, ab Stufe 10. Wirkt auf Ihr freundliches Ziel und wählt die Heilung nach fehlender Gesundheit: Reinigung des Glaubens oder Läutern, Heiliger Schock in Bewegung, Heiliges Licht im höchsten Rang unter 40 %, Heiliges Licht Rang 6 unter 65 %, Lichtblitz im höchsten Rang unter 85 %, Lichtblitz Rang 4 unter 95 %. Mit einem Gegner in Nahkampfreichweite: Siegel der Weisheit und, außerhalb von Schlachtzügen, Richturteil. Erinnerungen: Aura der Konzentration oder der Hingabe, Segen der Weisheit, Göttliche Gunst und Handauflegung für ein Ziel mit sehr wenig Gesundheit. Wen Sie heilen, bleibt Ihnen überlassen; Heilig-Paladine im Solospiel erhalten die integrierte Vergeltungsrotation.",
-- 8094efdd English: Retribution (SoD)
-- Context: Name of a Built In (premade) rotation, shown in the rotation list and picker: Paladin,
--     Season of Discovery (variant key: Retribution). Names in parentheses (guide or tool such as
--     Icy Veins, Wowhead, SimulationCraft, simulator, Hekili, Mobalytics, Warcraft Tavern) are
--     proper names and stay unchanged.
[37] = "Vergeltung (SoD)",
-- 0cc623b4 English: Season of Discovery melee from level 1 to 60, and the default for any Paladin
--     there. Keeps Seal of Martyrdom up (Righteousness until you have it), opens with Exorcism,
--     casts Divine Storm at three Holy Power, then by weapon speed: with a two-hander of 3.3
--     seconds or slower, Crusader Strike, Exorcism, Divine Storm and Judgement; with a faster one,
--     Judgement only as the seal runs out, then Exorcism, Crusader Strike and Divine Storm.
--     Consecration with mana or three close enemies, Holy Wrath on Undead and Demons (on anything
--     with Purifying Power engraved), Hammer of Wrath with mana to spare (always with Improved
--     Hammer of Wrath engraved). Runes are used as you engrave them. Reminders: Sanctity Aura, a
--     Blessing, Avenging Wrath with Aura Mastery, a heal between fights, Divine Shield when about
--     to die.
[38] = "Nahkampf in der Saison der Entdeckungen von Stufe 1 bis 60 und dort der Standard für jeden Paladin. Hält Siegel des Märtyrertums aufrecht (Rechtschaffenheit, bis Sie es haben), eröffnet mit Exorzismus, wirkt Göttlicher Sturm bei drei Heiliger Kraft, dann je nach Waffengeschwindigkeit: mit einer Zweihandwaffe von 3,3 Sekunden oder langsamer Kreuzfahrerstoß, Exorzismus, Göttlicher Sturm und Richturteil; mit einer schnelleren Richturteil nur, wenn das Siegel ausläuft, dann Exorzismus, Kreuzfahrerstoß und Göttlicher Sturm. Weihe bei genug Mana oder gegen drei nahe Gegner, Heiliger Zorn gegen Untote und Dämonen (gegen alles mit eingravierter Rune „Purifying Power“), Hammer des Zorns bei überschüssigem Mana (immer mit eingravierter Rune „Improved Hammer of Wrath“). Runen werden genutzt, sobald Sie sie gravieren. Erinnerungen: Aura der Heiligkeit, ein Segen, Zornige Vergeltung mit Aurenmeisterschaft, eine Heilung zwischen den Kämpfen, Gottesschild kurz vor dem Tod.",
-- a5e4661c English: Retribution (SoD, Icy Veins Phase 4)
[39] = "Vergeltung (SoD, Icy Veins Phase 4)",
-- 5f490b89 English: The older Phase 4 list from Icy Veins and Warcraft Tavern, also fine for
--     leveling, an alternative to the recommended Season of Discovery Retribution premade, off by
--     default: enable it and disable that one, or raise its priority. Judgement of the Crusader
--     once on elites and long fights, Seal of Martyrdom, Exorcism, Crusader Strike, Divine Storm
--     and Judgement on cooldown, Consecration with mana or three close enemies, Hammer of Wrath.
--     Same reminders as the recommended premade.
[40] = "Die ältere Liste für Phase 4 von Icy Veins und Warcraft Tavern, auch gut zum Leveln, eine Alternative zur empfohlenen integrierten Vergeltungsrotation der Saison der Entdeckungen, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Einmal Richturteil des Kreuzfahrers gegen Elitegegner und bei langen Kämpfen, Siegel des Märtyrertums, Exorzismus, Kreuzfahrerstoß, Göttlicher Sturm und Richturteil bei Abklingzeit-Ende, Weihe bei genug Mana oder gegen drei nahe Gegner, Hammer des Zorns. Dieselben Erinnerungen wie die empfohlene Rotation.",
-- 389af0dd English: Retribution, seal twisting (SoD)
[41] = "Vergeltung, Siegel-Twisting (SoD)",
-- e5b0a2f5 English: Off by default; enable it if you twist with a slow two-hander. Swaps between
--     Seal of Martyrdom and Seal of Command in the last 0.4 seconds before each swing, suggests
--     nothing on the global cooldown in the 1.9 seconds before it, judges while both seals linger,
--     and uses one filler per swing: Divine Storm at three Holy Power, Crusader Strike, Exorcism.
--     Needs a swing timer and practice.
[42] = "Standardmäßig deaktiviert; aktivieren Sie sie, wenn Sie mit einer langsamen Zweihandwaffe twisten. Wechselt in den letzten 0,4 Sekunden vor jedem Schlag zwischen Siegel des Märtyrertums und Siegel des Befehls, schlägt in den 1,9 Sekunden davor nichts auf der globalen Abklingzeit vor, richtet, solange beide Siegel nachwirken, und nutzt einen Füller pro Schlag: Göttlicher Sturm bei drei Heiliger Kraft, Kreuzfahrerstoß, Exorzismus. Benötigt einen Schlagtimer und Übung.",
-- ec76b9b6 English: Retribution, seal stacking (SoD)
[43] = "Vergeltung, Siegel-Stacking (SoD)",
-- 1def9d31 English: Off by default; enable it with the Soul of the Sealbearer rune or the six-piece
--     set that makes seals linger (Rotation Master cannot see either). Keeps both Seal of Command
--     and Seal of Martyrdom up, Divine Storm at three Holy Power, Crusader Strike, Exorcism, Holy
--     Wrath on Undead and Demons (on anything with Purifying Power engraved), Consecration, and
--     Judgement while both seals are up.
[44] = "Standardmäßig deaktiviert; aktivieren Sie sie mit der Rune Seele des Siegelträgers oder dem Sechsteile-Set, durch das Siegel nachwirken (Rotation Master kann keines von beiden erkennen). Hält Siegel des Befehls und Siegel des Märtyrertums beide aufrecht, Göttlicher Sturm bei drei Heiliger Kraft, Kreuzfahrerstoß, Exorzismus, Heiliger Zorn gegen Untote und Dämonen (gegen alles mit eingravierter Rune „Purifying Power“), Weihe und Richturteil, solange beide Siegel aktiv sind.",
-- 0fb3c120 English: Shockadin (SoD, simulator)
-- Context: Name of a Built In (premade) rotation, shown in the rotation list and picker: Paladin,
--     Season of Discovery (variant key: Shockadin). Names in parentheses (guide or tool such as Icy
--     Veins, Wowhead, SimulationCraft, simulator, Hekili, Mobalytics, Warcraft Tavern) are proper
--     names and stay unchanged.
[45] = "Shockadin (SoD, Simulation)",
-- 9a1756b6 English: Off by default; enable it if you deal damage with the Holy tree. It applies
--     with Holy as your main tree and Shock and Awe engraved. Seal of Martyrdom (else
--     Righteousness), judged as it runs out, Holy Shock to keep Sunlight up or at three Holy Power,
--     Exorcism and Crusader Strike. Same reminders as the Season of Discovery Retribution premade.
[46] = "Standardmäßig deaktiviert; aktivieren Sie sie, wenn Sie mit dem Heilig-Baum Schaden verursachen. Sie gilt, wenn Heilig Ihr Haupttalentbaum ist und die Rune „Shock and Awe“ eingraviert ist. Siegel des Märtyrertums (sonst Rechtschaffenheit), gerichtet, wenn es ausläuft, Heiliger Schock, um Sonnenlicht aufrechtzuerhalten, oder bei drei Heiliger Kraft, Exorzismus und Kreuzfahrerstoß. Dieselben Erinnerungen wie die integrierte Vergeltungsrotation der Saison der Entdeckungen.",
-- 924f353b English: Protection (SoD)
-- Context: Name of a Built In (premade) rotation, shown in the rotation list and picker: Paladin,
--     Season of Discovery (variant key: Protection). Names in parentheses (guide or tool such as
--     Icy Veins, Wowhead, SimulationCraft, simulator, Hekili, Mobalytics, Warcraft Tavern) are
--     proper names and stay unchanged.
[47] = "Schutz (SoD)",
-- 58619700 English: Season of Discovery tanking, chosen by Righteous Fury, an engraved Hammer of
--     the Righteous or Shield of Righteousness, or the Protection tree. Seal of Martyrdom, a pull
--     with Holy Shield, Avenger's Shield and Exorcism, Holy Shield kept up; on one target Hammer of
--     the Righteous, Shield of Righteousness, Exorcism, Avenger's Shield, Judgement, Divine Storm,
--     Consecration; with three or more enemies on you Hammer of the Righteous, Avenger's Shield,
--     Consecration, Shield of Righteousness, Exorcism. Reminders: Righteous Fury, Holy Shield
--     before a pull, Devotion Aura, Sanctuary or Kings, Avenging Wrath, Divine Protection below
--     40%, Lay on Hands, Hand of Reckoning in a group when your target attacks someone else.
[48] = "Tanken in der Saison der Entdeckungen, gewählt durch Zorn der Gerechtigkeit, einen gravierten Hammer der Rechtschaffenen oder Schild der Rechtschaffenheit oder den Schutzbaum. Siegel des Märtyrertums, ein Pull mit Heiligem Schild, Schild des Rächers und Exorzismus, Heiliger Schild aufrechterhalten; gegen ein Ziel Hammer der Rechtschaffenen, Schild der Rechtschaffenheit, Exorzismus, Schild des Rächers, Richturteil, Göttlicher Sturm, Weihe; wenn drei oder mehr Gegner gegen Sie kämpfen, Hammer der Rechtschaffenen, Schild des Rächers, Weihe, Schild der Rechtschaffenheit, Exorzismus. Erinnerungen: Zorn der Gerechtigkeit, Heiliger Schild vor einem Pull, Aura der Hingabe, Refugium oder Könige, Zornige Vergeltung, Göttlicher Schutz unter 40 %, Handauflegung, Hand der Abrechnung in einer Gruppe, wenn Ihr Ziel jemand anderen angreift.",
-- c138082a English: Protection (SoD, simulator)
-- Context: Name of a Built In (premade) rotation, shown in the rotation list and picker: Paladin,
--     Season of Discovery (variant key: Protection / simulator). Names in parentheses (guide or
--     tool such as Icy Veins, Wowhead, SimulationCraft, simulator, Hekili, Mobalytics, Warcraft
--     Tavern) are proper names and stay unchanged.
[49] = "Schutz (SoD, Simulation)",
-- cfa4b56e English: The simulator tank list, an alternative to the recommended Season of Discovery
--     Protection premade, off by default: enable it and disable that one, or raise its priority.
--     Judgement whenever a seal is up, the seal renewed just before it runs out, Holy Shield,
--     Avenger's Shield, Hammer of the Righteous, Exorcism, Shield of Righteousness last. Same
--     reminders as the recommended premade.
[50] = "Die Tankliste von Simulation, eine Alternative zur empfohlenen integrierten Schutzrotation der Saison der Entdeckungen, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Richturteil, wann immer ein Siegel aktiv ist, das Siegel kurz vor dem Auslaufen erneuert, Heiliger Schild, Schild des Rächers, Hammer der Rechtschaffenen, Exorzismus, Schild der Rechtschaffenheit zuletzt. Dieselben Erinnerungen wie die empfohlene integrierte Rotation.",
-- e757b87a English: Holy (SoD)
-- Context: Name of a Built In (premade) rotation, shown in the rotation list and picker: Paladin,
--     Season of Discovery (variant key: Holy). Names in parentheses (guide or tool such as Icy
--     Veins, Wowhead, SimulationCraft, simulator, Hekili, Mobalytics, Warcraft Tavern) are proper
--     names and stay unchanged.
[51] = "Heilig (SoD)",
-- 45b566d4 English: Season of Discovery healing in a group, chosen by an engraved Beacon of Light,
--     Divine Light or Sacred Shield, or the Holy tree without Crusader Strike. Acts on your
--     friendly target: Cleanse, Holy Shock while moving or below 30%, Divine Light (Holy Light when
--     mana is under half) below 60%, Flash of Light below 90%. With an enemy in melee range it only
--     keeps a seal up. Reminders: Beacon of Light and Sacred Shield on the target that lacks them,
--     Concentration or Devotion Aura, Blessing of Wisdom, Divine Favor and Lay on Hands for a
--     target that is very low. The guides behind it are from Phase 4; choosing whom to heal stays
--     with you.
[52] = "Heilung in einer Gruppe in der Saison der Entdeckungen, gewählt durch eine gravierte Flamme des Glaubens, Göttliches Licht oder Geheiligten Schild oder den Heilig-Baum ohne Kreuzfahrerstoß. Wirkt auf Ihr freundliches Ziel: Reinigung des Glaubens, Heiliger Schock in Bewegung oder unter 30 %, Göttliches Licht (Heiliges Licht, wenn das Mana unter der Hälfte liegt) unter 60 %, Lichtblitz unter 90 %. Mit einem Gegner in Nahkampfreichweite hält sie nur ein Siegel aufrecht. Erinnerungen: Flamme des Glaubens und Geheiligter Schild auf dem Ziel, dem sie fehlen, Aura der Konzentration oder der Hingabe, Segen der Weisheit, Göttliche Gunst und Handauflegung für ein Ziel mit sehr wenig Gesundheit. Die zugrunde liegenden Leitfäden stammen aus Phase 4; wen Sie heilen, bleibt Ihnen überlassen.",
-- e2f2ad93 English: Holy, Holy Light first (SoD, Wowhead)
[53] = "Heilig, Heiliges Licht zuerst (SoD, Wowhead)",
-- 12186f26 English: Wowhead's Phase 4 healing order for crit-heavy gear, an alternative to the
--     recommended Season of Discovery Holy premade, off by default: enable it and disable that one,
--     or raise its priority. Divine Light or Holy Light below 75%, then Cleanse, Holy Shock for
--     small deficits or while moving, Flash of Light below 95%. Same reminders as the recommended
--     premade.
[54] = "Die Heilreihenfolge von Wowhead für Phase 4 bei Ausrüstung mit viel kritischer Trefferchance, eine Alternative zur empfohlenen integrierten Heilig-Rotation der Saison der Entdeckungen, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Göttliches Licht oder Heiliges Licht unter 75 %, dann Reinigung des Glaubens, Heiliger Schock bei kleinen Defiziten oder in Bewegung, Lichtblitz unter 95 %. Dieselben Erinnerungen wie die empfohlene integrierte Rotation.",
-- a115bc01 English: Recommended for Retribution, from level 10 in the Retribution specialization.
--     Keeps Inquisition up (cast at 3 Holy Power, refreshed in its last 3 seconds; from 81), spends
--     Templar's Verdict at full Holy Power or on a free proc before generating more, then Hammer of
--     Wrath, Crusader Strike, Judgment and Exorcism, and Templar's Verdict at 3 when nothing else
--     is ready. In Avenging Wrath it spends at once and puts Judgment ahead of Crusader Strike. Two
--     or more enemies on you switch to Divine Storm, with Hammer of the Righteous when four are
--     close. Pulls from range with Judgment or Exorcism, and suggests Word of Glory when you are
--     solo and in danger. Reminders: Seal of Truth when another seal is active or none (Seal of
--     Righteousness is kept), Blessing of Kings or Might, Rebuke, Avenging Wrath and Guardian of
--     Ancient Kings with Inquisition up on elites, Holy Avenger in wings, Execution Sentence and
--     Light's Hammer, and Divine Protection and Lay on Hands when low. Seal of Righteousness for
--     packs and glyph choices stay with you.
[55] = "Empfohlen für Vergeltung ab Stufe 10 in der Spezialisierung Vergeltung. Hält Inquisition aufrecht (bei 3 Heiliger Kraft gewirkt, in ihren letzten 3 Sekunden erneuert; ab Stufe 81), gibt Urteil des Templers bei voller Heiliger Kraft oder bei einem kostenlosen Proc aus, bevor sie mehr erzeugt, dann Hammer des Zorns, Kreuzfahrerstoß, Richturteil und Exorzismus und Urteil des Templers bei 3, wenn nichts anderes bereit ist. Während Zorniger Vergeltung gibt sie sofort aus und stellt Richturteil vor Kreuzfahrerstoß. Zwei oder mehr Gegner gegen Sie wechseln zu Göttlicher Sturm, mit Hammer der Rechtschaffenen, wenn vier nah sind. Zieht aus der Distanz mit Richturteil oder Exorzismus und schlägt Wort der Herrlichkeit vor, wenn Sie solo und in Gefahr sind. Erinnerungen: Siegel der Wahrheit, wenn ein anderes Siegel oder keines aktiv ist (Siegel der Rechtschaffenheit bleibt erhalten), Segen der Könige oder der Macht, Zurechtweisung, Zornige Vergeltung und Wächter der Uralten Könige bei aktiver Inquisition gegen Elitegegner, Heiliger Rächer während Zorniger Vergeltung, Richtspruch und Hammer des Lichts sowie Göttlicher Schutz und Handauflegung bei niedriger Gesundheit. Siegel der Rechtschaffenheit für Gruppen und die Wahl der Glyphen bleiben Ihnen überlassen.",
-- 73ee5d82 English: Exorcism first (Warcraft Tavern)
[56] = "Exorzismus zuerst (Warcraft Tavern)",
-- efa8e3a8 English: An alternative to the recommended Retribution premade, off by default: enable
--     it and disable that one, or raise its priority. Exorcism on every cooldown and Art of War
--     reset comes first; Inquisition is cast at any Holy Power when it is missing and refreshed at
--     3 in its last 20 seconds; then Crusader Strike, Judgment, Templar's Verdict and Hammer of
--     Wrath (first in wings with Sanctified Wrath). Two or more enemies use Crusader Strike,
--     Light's Hammer, Judgment, Divine Storm and Hammer of Wrath. Avenging Wrath and Guardian of
--     Ancient Kings are suggested only on elites. The guide's Seal of Righteousness on any cleave
--     is left to you.
[57] = "Eine Alternative zur empfohlenen integrierten Vergeltungsrotation, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Exorzismus bei jedem Abklingzeit-Ende und jedem Zurücksetzen durch Kriegskunst kommt zuerst; Inquisition wird bei beliebiger Heiliger Kraft gewirkt, wenn sie fehlt, und bei 3 in ihren letzten 20 Sekunden erneuert; dann Kreuzfahrerstoß, Richturteil, Urteil des Templers und Hammer des Zorns (zuerst während Zorniger Vergeltung mit Geweihtem Zorn). Zwei oder mehr Gegner nutzen Kreuzfahrerstoß, Hammer des Lichts, Richturteil, Göttlicher Sturm und Hammer des Zorns. Zornige Vergeltung und Wächter der Uralten Könige werden nur gegen Elitegegner vorgeschlagen. Das Siegel der Rechtschaffenheit des Leitfadens bei jedem Cleave bleibt Ihnen überlassen.",
-- 0c1b3a03 English: Recommended for Protection, from level 10 in the Protection specialization.
--     Pulls with Avenger's Shield, then Avenger's Shield on a Grand Crusader proc, Avenger's
--     Shield, Hammer of Wrath, Crusader Strike, Judgment, your level-90 talent, Consecration, Holy
--     Wrath and Sacred Shield. Three or more enemies on you switch to Avenger's Shield,
--     Consecration, Hammer of the Righteous, Judgment and Holy Wrath. Shield of the Righteous,
--     Eternal Flame and Word of Glory are off the global cooldown, so they light beside the
--     rotation: Shield of the Righteous whenever you can afford it, Eternal Flame on yourself when
--     it is running out with 3 Holy Power and three Bastion of Glory stacks, Word of Glory below
--     half health without that talent. Other reminders: Righteous Fury, Seal of Insight when
--     another seal (except Righteousness) or none is active, blessings, Rebuke, Sacred Shield,
--     Avenging Wrath and Holy Avenger while you are tanking, and Guardian of Ancient Kings, Ardent
--     Defender, Divine Protection and Lay on Hands by your health. It cannot see incoming damage,
--     so plan big defensives yourself.
[58] = "Empfohlen für Schutz ab Stufe 10 in der Spezialisierung Schutz. Zieht mit Schild des Rächers, dann Schild des Rächers bei einem Proc von Oberster Kreuzfahrer, Schild des Rächers, Hammer des Zorns, Kreuzfahrerstoß, Richturteil, Ihr Talent der Stufe 90, Weihe, Heiliger Zorn und Geheiligter Schild. Drei oder mehr Gegner gegen Sie wechseln zu Schild des Rächers, Weihe, Hammer der Rechtschaffenen, Richturteil und Heiliger Zorn. Schild der Rechtschaffenen, Ewige Flamme und Wort der Herrlichkeit liegen nicht auf der globalen Abklingzeit, daher leuchten sie neben der Rotation auf: Schild der Rechtschaffenen, wann immer Sie es sich leisten können, Ewige Flamme auf Ihnen selbst, wenn sie ausläuft, mit 3 Heiliger Kraft und drei Stapeln Bastion der Herrlichkeit, Wort der Herrlichkeit unter halber Gesundheit ohne dieses Talent. Weitere Erinnerungen: Zorn der Gerechtigkeit, Siegel der Einsicht, wenn ein anderes Siegel (außer Rechtschaffenheit) oder keines aktiv ist, Segen, Zurechtweisung, Geheiligter Schild, Zornige Vergeltung und Heiliger Rächer, während Sie tanken, sowie Wächter der Uralten Könige, Unermüdlicher Verteidiger, Göttlicher Schutz und Handauflegung je nach Ihrer Gesundheit. Sie kann eingehenden Schaden nicht sehen, planen Sie große Defensivfähigkeiten also selbst.",
-- e3cb6b71 English: Pool Holy Power (simulator)
[59] = "Heilige Kraft sammeln (Simulation)",
-- 0709f739 English: An alternative to the recommended Protection premade, off by default: enable it
--     and disable that one, or raise its priority. Follows the simulator's tank lists: Shield of
--     the Righteous waits for full Holy Power unless you fall below 40% health or Divine Purpose
--     makes it free; Eternal Flame just before it fades with more than two Bastion of Glory stacks;
--     Sacred Shield kept up; Holy Avenger and Avenging Wrath on cooldown. Generators run Crusader
--     Strike, Judgment, then Avenger's Shield, Holy Wrath, the level-90 talent and Hammer of Wrath,
--     with the same three-enemy AoE order. Boss-timed defensives are yours.
[60] = "Eine Alternative zur empfohlenen integrierten Schutzrotation, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Folgt den Tanklisten des Simulators: Schild der Rechtschaffenen wartet auf volle Heilige Kraft, außer Sie fallen unter 40 % Gesundheit oder Göttliche Bestimmung macht es kostenlos; Ewige Flamme kurz vor dem Auslaufen mit mehr als zwei Stapeln Bastion der Herrlichkeit; Geheiligter Schild aufrechterhalten; Heiliger Rächer und Zornige Vergeltung bei Abklingzeit-Ende. Die Generatoren laufen Kreuzfahrerstoß, Richturteil, dann Schild des Rächers, Heiliger Zorn, das Talent der Stufe 90 und Hammer des Zorns, mit derselben Flächenreihenfolge ab drei Gegnern. Auf Bosse abgestimmte Defensivfähigkeiten liegen bei Ihnen.",
-- ba77c874 English: For Holy, from level 10 in the Holy specialization. With a friend targeted it
--     heals: at 3 Holy Power (or Divine Purpose) Light of Dawn when three people near you are hurt,
--     else Eternal Flame on a target without it, else Word of Glory; Holy Shock on cooldown;
--     Infusion of Light into Holy Radiance or Divine Light, three Selfless Healer stacks into Holy
--     Radiance or Flash of Light; Flash of Light below 35%; Holy Radiance for a hurt group; Divine
--     Light, then Holy Light to top off. With an enemy targeted it deals damage: Holy Shock,
--     Judgment, Crusader Strike, Holy Prism, Execution Sentence, Hammer of Wrath, Denounce.
--     Reminders: Seal of Insight when another seal (except Righteousness) or none is active,
--     blessings, Rebuke, Beacon of Light and Sacred Shield on your focus (set the tank as focus),
--     Divine Plea below 60% mana, Light's Hammer and your healing cooldowns when three people are
--     below 70%, Lay on Hands on a dying target. Choosing whom to heal, dispels and mouseover
--     healing stay with you.
[61] = "Für Heilig ab Stufe 10 in der Spezialisierung Heilig. Mit einem Verbündeten im Ziel heilt sie: bei 3 Heiliger Kraft (oder Göttlicher Bestimmung) Licht der Morgendämmerung, wenn drei Personen in Ihrer Nähe verletzt sind, sonst Ewige Flamme auf ein Ziel ohne sie, sonst Wort der Herrlichkeit; Heiliger Schock bei Abklingzeit-Ende; Lichtenergie in Heiliges Strahlen oder Göttliches Licht, drei Stapel Selbstloser Heiler in Heiliges Strahlen oder Lichtblitz; Lichtblitz unter 35 %; Heiliges Strahlen für eine verletzte Gruppe; Göttliches Licht, dann Heiliges Licht zum Auffüllen. Mit einem Gegner im Ziel verursacht sie Schaden: Heiliger Schock, Richturteil, Kreuzfahrerstoß, Heiliges Prisma, Richtspruch, Hammer des Zorns, Denunzierung. Erinnerungen: Siegel der Einsicht, wenn ein anderes Siegel (außer Rechtschaffenheit) oder keines aktiv ist, Segen, Zurechtweisung, Flamme des Glaubens und Geheiligter Schild auf Ihrem Fokus (legen Sie den Tank als Fokus fest), Göttliche Bitte unter 60 % Mana, Hammer des Lichts und Ihre Heil-Abklingzeiten, wenn drei Personen unter 70 % sind, Handauflegung auf ein sterbendes Ziel. Wen Sie heilen, Bannungen und Mouseover-Heilung bleiben Ihnen überlassen.",
-- fce883af English: For levels 1 to 9, and any paladin who has not chosen a specialization yet; a
--     specialization's premade takes over as soon as you pick one. Pulls from range with Judgment,
--     then Crusader Strike and Judgment, with Hammer of Justice when you are solo and below half
--     health and Word of Glory below 40%. Reminders: Seal of Command (Seal of Truth from 24) when
--     you are not in it, Blessing of Kings, Rebuke, and Flash of Light out of combat when you are
--     hurt.
[62] = "Für Stufe 1 bis 9 und jeden Paladin, der noch keine Spezialisierung gewählt hat; die integrierte Rotation einer Spezialisierung übernimmt, sobald Sie eine wählen. Zieht aus der Distanz mit Richturteil, dann Kreuzfahrerstoß und Richturteil, mit Hammer der Gerechtigkeit, wenn Sie solo und unter halber Gesundheit sind, und Wort der Herrlichkeit unter 40 %. Erinnerungen: Siegel des Befehls (Siegel der Wahrheit ab Stufe 24), wenn Sie nicht darin sind, Segen der Könige, Zurechtweisung und Lichtblitz außerhalb des Kampfes, wenn Sie verletzt sind.",
}
